let rotationNote='';
function injuryText(p){return p.injury?H.kindLabel(p.injury.kind)+' · '+p.injury.remaining+'경기 휴식':'';}
function loadEnergy(p){return state?.players[p.id]?.energy??p.energy;}
function fitnessBadge(p){return p.injury?'<span class="fitness-badge injured">'+injuryText(p)+'</span>':loadEnergy(p)<65?'<span class="fitness-badge caution">피로 주의</span>':'<span class="fitness-badge fit">출전 가능</span>';}
function clubFacesMarkup(players){
 const faces=[...players].sort((a,b)=>b[S.primaryKey(b)]-a[S.primaryKey(a)]||a.id.localeCompare(b.id,'en')).slice(0,3);
 return '<section class="club-faces"><div class="panel-heading"><h2>우리 구단의 얼굴들</h2><span>현재 주요 능력 상위 '+faces.length+'명</span></div><div class="club-face-grid">'+faces.map(p=>'<article class="club-face"><div class="club-face-heading">'+Portraits.html(p,{size:'large'})+'<div><span>'+p.pos+' · 주요 능력 '+p[S.primaryKey(p)]+'</span><h3>'+playerUiText(p.name)+'</h3></div></div>'+playerCharacterMarkup(p)+'<button class="profile-inline-button" data-player-detail="'+playerUiText(p.identity)+'" aria-label="'+playerUiText(p.name)+' 선수 상세 보기">선수 상세 카드 ↗</button></article>').join('')+'</div></section>';
}
function rotateSquad(){try{const result=H.rotate(season);selected=null;rotationNote=result.changes.length?'체력 우선으로 '+result.changes.length+'자리를 바꿨습니다. 포메이션과 전술은 유지했습니다.':'현재 선발이 체력 우선 기준에 맞습니다.';$('notice').hidden=true;save();render();}catch(err){notify(err.message);}}
function healthReviewMarkup(){if(state?.phase!=='full')return '';const tired=Object.values(state.players).filter(p=>p.minutes>=30&&p.energy<50).sort((a,b)=>b.minutes-a.minutes||a.energy-b.energy).slice(0,3);return '<div class="load-review"><div class="eyebrow">AFTER THE WHISTLE</div><h3>다음 경기를 위한 몸 상태.</h3><p>'+(tired.length?tired.map(p=>p.name+' · 체력 '+Math.round(p.energy)+' / '+p.minutes+'분 출전').join('<br>'):'출전 선수들이 이번 경기를 마쳤습니다.')+'</p><small>결과를 확정하면 경기 후 부상 판정과 회복 상태를 확인할 수 있습니다. 피로가 큰 선수의 연속 출전과 긴 압박은 위험을 높입니다.</small></div>';}
function renderHealth(){
 const players=Object.values(season.squad),injured=players.filter(p=>p.injury),caution=players.filter(p=>!p.injury&&loadEnergy(p)<65),fit=players.length-injured.length,prep=state?.phase==='prep',report=season.health.lastReport,lineup=state?.lineup.map(id=>season.squad[id])||[],mean=lineup.length?lineup.reduce((n,p)=>n+loadEnergy(p),0)/11:0;
 $('health-summary').innerHTML='<div class="health-band"><div><span>출전 가능한 선수</span><strong>'+fit+'<small> / 18명</small></strong></div><div><span>부상으로 휴식</span><strong class="'+(injured.length?'health-orange':'')+'">'+injured.length+'<small>명</small></strong></div><div><span>피로 주의</span><strong class="'+(caution.length?'health-orange':'')+'">'+caution.length+'<small>명</small></strong></div><button id="open-health" class="text-button">몸 상태와 선발 관리 →</button></div>';$('open-health').onclick=()=>setView('squad');
 const incidents=report?.incidents||[],recovered=report?.recovered||[];
 $('squad-health').innerHTML='<div class="health-hero"><div><div class="eyebrow">SQUAD MANAGEMENT / SEASON '+String(season.year).padStart(2,'0')+'</div><h1>긴 시즌은, 열여덟 명으로.</h1><p>한 명의 에이스보다 오래 버티는 선수단.<br>지친 선수에게 휴식을 주고, 벤치의 다음 주인공을 찾아보세요.</p></div><div class="health-hero-count"><span>AVAILABLE</span><strong>'+fit+'<small> / 18</small></strong><span>'+injured.length+'명 휴식 · '+caution.length+'명 피로 주의</span></div></div>'+clubFacesMarkup(players)+'<div class="rotation-panel"><div><div class="eyebrow">ROTATE THE ELEVEN</div><h2>이번 경기 선발 관리</h2><p>'+(state?'선발 평균 체력 '+Math.round(mean)+' · '+state.formation.split('').join('-')+' · '+labels[state.tactic]:'시즌 종료 · 선수들은 다음 시즌 시작 때 회복합니다.')+'</p><small>같은 포지션에서 출전 가능한 선수의 체력을 우선합니다. 능력이 높은 선수를 쉬게 할 수도 있으니 마지막으로 선발을 확인하세요.</small></div><div class="rotation-actions"><button id="rotate-squad" class="'+(prep?'primary':'secondary')+'" '+(prep?'':'disabled')+'>체력 우선 자동 선발</button><button id="rotation-match" class="secondary" '+(state?'':'disabled')+'>'+(state?.phase==='full'?'경기 결과로 돌아가기':'경기장 선발 확인 →')+'</button></div></div>'+(rotationNote?'<p class="rotation-note" role="status">'+rotationNote+'</p>':'')+'<div class="health-columns"><section class="medical-room"><div class="panel-heading"><h2>휴식이 필요한 선수</h2><span>'+injured.length+'명</span></div>'+(injured.length?'<div class="injury-list">'+injured.map(p=>'<article class="injury-card"><div><span class="position">'+p.pos+' · #'+p.no+'</span><h3>'+p.name+'</h3><span class="fitness-badge injured">'+H.kindLabel(p.injury.kind)+'</span></div><div class="injury-rest"><strong>'+p.injury.remaining+'</strong><span>경기 휴식</span></div></article>').join('')+'</div>':'<div class="health-empty"><span class="health-check" aria-hidden="true">✓</span><p>현재 부상 선수는 없습니다.<br>선발을 나누어 체력을 관리하세요.</p></div>')+'<p class="health-footnote">리그와 컵에서 한 경기를 쉬면 휴식 횟수가 줄어듭니다. 회복 훈련은 체력을 올리며, 부상 기간은 경기 휴식으로 채웁니다.</p></section><section class="load-room"><div class="panel-heading"><h2>피로와 출전 균형</h2><span>현재 체력 65 미만</span></div>'+(caution.length?'<div class="fatigue-list">'+caution.slice().sort((a,b)=>loadEnergy(a)-loadEnergy(b)).map(p=>'<div class="fatigue-row"><span><b>'+p.name+'</b><small>'+p.pos+' · '+(state?.lineup.includes(p.id)?'이번 선발':'벤치')+'</small></span><strong>'+Math.round(loadEnergy(p))+'</strong></div>').join('')+'</div>':'<div class="health-empty"><p>피로 주의 선수가 없습니다.<br>연속 출전이 많은 선수도 살펴보세요.</p></div>')+'<p class="health-footnote">피로 주의는 선발을 살펴보는 기준입니다. 경기 후 체력, 실제 출전 시간과 압박 시간을 함께 반영해 부상을 판정합니다.</p></section></div><section class="medical-report"><div class="panel-heading"><h2>최근 경기 후 점검</h2><span>'+(report?report.year+'시즌 · '+(report.competition==='cup'?'컵 경기':report.round+'R'):'첫 점검 대기')+'</span></div>'+(report?'<div class="medical-report-lines">'+(incidents.length?incidents.map(p=>'<p class="new-injury"><span>휴식 판정</span><b>'+p.name+'</b> · '+H.kindLabel(p.kind)+' · '+p.remaining+'경기</p>').join(''):'<p><span>부상 판정</span>새 부상 선수 없음</p>')+(recovered.length?recovered.map(p=>'<p class="recovered"><span>복귀 가능</span><b>'+p.name+'</b> · 다음 경기 출전 가능</p>').join(''):'')+'</div>':'<p class="health-footnote">경기 결과를 확정하면 새 부상과 복귀 선수를 알려드립니다. 이전에 진행한 경기에는 부상을 소급 적용하지 않습니다.</p>')+'</section>';
 $('rotate-squad').onclick=rotateSquad;$('rotation-match').onclick=()=>setView('match');
 $('match-health').innerHTML=state?'<div class="match-load-strip"><span>선발 체력 <b>'+Math.round(mean)+'</b> · 부상 '+injured.length+'명</span><button id="rotate-match" class="text-button" '+(prep?'':'disabled')+'>체력 우선 자동 선발</button></div>':'';if($('rotate-match'))$('rotate-match').onclick=rotateSquad;
}
